def estadisticas(numeros):
    # Devuelve (minimo, maximo, media, mediana) o None si está vacía
    pass

exercises.solution:
def estadisticas(numeros):
    if not numeros:
        return None
    ordenados = sorted(numeros)          # lista NUEVA: el original no cambia
    n = len(ordenados)
    media = sum(ordenados) / n
    mitad = n // 2
    if n % 2 == 1:
        mediana = ordenados[mitad]
    else:
        mediana = (ordenados[mitad - 1] + ordenados[mitad]) / 2
    return (ordenados[0], ordenados[-1], round(media, 2), round(mediana, 2))

