def comparar_gustos(a, b):
    gustos_a = set(a)
    gustos_b = set(b)
    return {
        "comunes": sorted(gustos_a & gustos_b),
        "solo_a": sorted(gustos_a - gustos_b),
        "solo_b": sorted(gustos_b - gustos_a),
        "total_distintos": len(gustos_a | gustos_b),
    }

