exercises.solution:
def analizar(numeros):
    pares = list(zip(numeros, numeros[1:]))      # (anterior, siguiente)
    saltos = [abs(b - a) for a, b in pares]
    return {
        "todos_positivos": all([n > 0 for n in numeros]),
        "hay_cero": any([n == 0 for n in numeros]),
        "ordenada": all([a <= b for a, b in pares]),
        "maximo_salto": max(saltos, default=0),
    }

