def crear_matriz(filas, columnas, valor):
    return [[valor] * columnas for _ in range(filas)]


def transponer(matriz):
    if not matriz:
        return []
    columnas = len(matriz[0])
    resultado = []
    for j in range(columnas):
        nueva_fila = []
        for fila in matriz:
            nueva_fila.append(fila[j])
        resultado.append(nueva_fila)
    return resultado

