def clave_ranking(alumno):
    return (-alumno["nota"], alumno["nombre"])


def ranking(alumnos):
    ordenados = sorted(alumnos, key=clave_ranking)
    resultado = []
    for posicion, alumno in enumerate(ordenados, start=1):
        resultado.append((posicion, alumno["nombre"], alumno["nota"]))
    return resultado

