exercises.solution:
def fusionar_stock(stock, movimientos):
    resultado = dict(stock)                 # copia: no tocamos el original
    for producto, cantidad in movimientos.items():
        resultado[producto] = resultado.get(producto, 0) + cantidad
    return {p: c for p, c in resultado.items() if c > 0}

