exercises.solution:
def agrupar_anagramas(palabras):
    grupos = {}                      # firma (tupla de letras ordenadas) -> lista de palabras
    for palabra in palabras:
        firma = tuple(sorted(palabra.lower()))
        grupo = grupos.setdefault(firma, [])
        if palabra not in grupo:
            grupo.append(palabra)
    return list(grupos.values())

