def sudoku_valido(tablero):
    # Comprueba filas, columnas y cajas de 3x3 (ignorando los ceros)
    pass

exercises.solution:
def sin_repetidos(valores):
    vistos = set()
    for v in valores:
        if v != 0:
            if v in vistos:
                return False
            vistos.add(v)
    return True


def sudoku_valido(tablero):
    for fila in tablero:
        if not sin_repetidos(fila):
            return False
    for j in range(9):
        columna = [tablero[i][j] for i in range(9)]
        if not sin_repetidos(columna):
            return False
    for fila_inicio in range(0, 9, 3):
        for col_inicio in range(0, 9, 3):
            caja = []
            for i in range(fila_inicio, fila_inicio + 3):
                caja.extend(tablero[i][col_inicio:col_inicio + 3])
            if not sin_repetidos(caja):
                return False
    return True

