    # Devuelve una matriz de enteros: -1 en las minas, nº de minas vecinas en el resto
    pass

exercises.solution:
def contar_minas(tablero):
    filas = len(tablero)
    resultado = []
    for i in range(filas):
        columnas = len(tablero[i])
        fila_resultado = []
        for j in range(columnas):
            if tablero[i][j] == "*":
                fila_resultado.append(-1)
                continue
            minas = 0
            for di in (-1, 0, 1):
                for dj in (-1, 0, 1):
                    vi = i + di
                    vj = j + dj
                    if 0 <= vi < filas and 0 <= vj < columnas and tablero[vi][vj] == "*":
                        minas += 1
            fila_resultado.append(minas)
        resultado.append(fila_resultado)
    return resultado

