import copy


def agregar_contacto(agenda, nombre, telefono):
    if nombre not in agenda:
        agenda[nombre] = {"telefonos": [telefono], "etiquetas": set()}
        return True
    telefonos = agenda[nombre]["telefonos"]
    if telefono not in telefonos:
        telefonos.append(telefono)
    return False


def etiquetar(agenda, nombre, etiqueta):
    if nombre not in agenda:
        return False
    agenda[nombre]["etiquetas"].add(etiqueta)
    return True


def eliminar_contacto(agenda, nombre):
    return agenda.pop(nombre, None)


def buscar(agenda, texto):
    texto = texto.lower()
    return sorted([nombre for nombre in agenda if texto in nombre.lower()])


def por_etiqueta(agenda, etiqueta):
    return sorted([nombre for nombre, datos in agenda.items() if etiqueta in datos["etiquetas"]])


def resumen(agenda):
    filas = []
    for nombre in sorted(agenda):
        datos = agenda[nombre]
        filas.append((nombre, len(datos["telefonos"]), tuple(sorted(datos["etiquetas"]))))
    return filas


def exportar(agenda):
    return copy.deepcopy(agenda)

