exercises.solution:
def a_registros(cabecera, filas):
    registros = []
    for fila in filas:
        if len(fila) == len(cabecera):
            registros.append(dict(zip(cabecera, fila)))
    return registros


def importe(registro):
    return registro["unidades"] * registro["precio"]


def clave_desc(par):
    clave, valor = par
    return (-valor, clave)


def total_por(registros, campo):
    totales = {}
    for r in registros:
        totales[r[campo]] = totales.get(r[campo], 0) + importe(r)
    redondeados = {clave: round(total, 2) for clave, total in totales.items()}
    return dict(sorted(redondeados.items(), key=clave_desc))


def top_productos(registros, n):
    unidades = {}
    for r in registros:
        unidades[r["producto"]] = unidades.get(r["producto"], 0) + r["unidades"]
    return sorted(unidades.items(), key=clave_desc)[:n]


def informe(cabecera, filas):
    registros = a_registros(cabecera, filas)
    por_region = total_por(registros, "region")
    productos = {}
    for r in registros:
        productos.setdefault(r["region"], set()).add(r["producto"])
    return {
        "num_ventas": len(registros),
        "importe_total": round(sum([importe(r) for r in registros]), 2),
        "por_region": por_region,
        "por_producto": total_por(registros, "producto"),
        "mejor_region": list(por_region)[0] if por_region else None,
        "productos_por_region": {region: sorted(prods) for region, prods in productos.items()},
    }

